"""The exploratory two look satisficing analysis end to end on synthetic snack data. No real data are used."""

from __future__ import annotations

import numpy as np

from overload.experiments import search_confirmatory as sc
from overload.experiments import two_look_snack as tl
from overload.search import two_look_satisficing
from overload.snack import SET_SIZES, Block, SnackData

LAM = 1.0


def _simulate(rng: np.random.Generator, trials: int = 60, participants: int = 10) -> SnackData:
    """Choices, distinct items looked at and response times generated by two look satisficing itself."""
    blocks = []
    for n in SET_SIZES:
        values = np.clip(np.round(rng.normal(rng.uniform(-1, 2, (trials, 1)), 1.2, (trials, n))), -3, 3)
        choice, seen, rt = np.zeros(trials, int), np.zeros((trials, n), bool), np.zeros(trials)
        for t in range(trials):
            q = np.exp(0.5 * LAM * values[t])
            q /= q.sum()
            h = np.exp(0.5 * LAM * (values[t] - 3.0))
            hits, k = np.zeros(n, int), 0
            while True:
                i = int(rng.choice(n, p=q))
                k += 1
                seen[t, i] = True
                if rng.random() < h[i]:
                    hits[i] += 1
                    if hits[i] == 2:
                        choice[t] = i
                        break
            rt[t] = 1000.0 * (0.5 + 0.3 * k) * np.exp(rng.normal(0, 0.1))
        blocks.append(Block(n, values, choice, seen, rng.integers(0, participants, trials), rt))
    return SnackData(tuple(blocks), tuple(range(participants)))


def test_end_to_end_on_data_from_the_model():
    data = _simulate(np.random.default_rng(5))
    tl._STATE.update(data=data, prep=sc.prepare(data))
    point = tl.run_replicate(-1)
    assert np.allclose(point["lambda"], LAM, atol=0.35)
    # time generated by the model's looks is predicted best by the model's looks
    assert point["E1"]["TLS"]["error"] < point["E1"]["CL"]["error"]
    assert point["E2"]["looks_TLS"] > 0.1
    # predicted distinct items track the simulated ones
    assert np.allclose(point["E3"]["predicted"], point["E3"]["observed"], rtol=0.2)
    reps = [tl.run_replicate(b) for b in (0, 1)]
    summary = tl.summarize_all(point, reps)
    assert set(summary) >= {"E1", "E2", "E3", "uniform_attention"}
    assert "E1, time held out" in tl.table(summary)


def test_level_forecasts_equal_the_item_model():
    rng = np.random.default_rng(6)
    data = _simulate(rng, trials=8)
    prep = sc.prepare(data)
    blk = prep["blocks"][1]
    from overload.snack_search import two_look_levels

    looks, distinct = two_look_levels(0.9, blk["levels"])
    for t, v in enumerate(blk["values"]):
        _, lk, ds = two_look_satisficing(0.9, v, 3.0)
        assert np.isclose(looks[t], lk, rtol=1e-10) and np.isclose(distinct[t], ds, rtol=1e-10)
